  await refreshTracking(shipments(2).map((s) => ({ ...s, status: 'delivered' })), carrier);
  assert.equal(carrier.requests.length, 0);
});

test('asks about each tracking number once', async () => {
  const carrier = fakeCarrier();
  const [one] = shipments(1);
  await refreshTracking([one, one], carrier);
  assert.deepEqual(carrier.requests.map((request) => request.payload.trackingNumbers), [[one.trackingNumber]]);
});
